def _dbody120(name):
    m = _re120.search(r'\[delayed_gcode ' + _re120.escape(name) + r'\]\n(.*?)(?=\n\[|\Z)',
                      _cp120txt, _re120.S)
    return klipper_strip('\n'.join(l[4:] if l.startswith('    ') else l
                                    for l in m.group(1).split('\n')[1:]))

