    last = 0.0; tot = 0.0
    for l in open(p):
        m = re.match(r'G1 .*E(-?[\d.]+)', l)
        if m:
            v = float(m.group(1)); tot += v - last; last = v
        if l.startswith('G92 E'):
            last = float(l.split('E')[1])
    return tot

